"use client"

import { useEffect, useState } from "react"
import type { MatchDetail } from "@mrdoge/protocol"
import { getMrDogeClient } from "@/registry/mrdoge-ui/mrdoge-client/mrdoge-client"

/** undefined = loading, null = subscribe failed (no fallback — that's an honest empty state). */
export function useLiveMatch(matchId: string) {
  const [match, setMatch] = useState<MatchDetail | null | undefined>(undefined)

  useEffect(() => {
    let cancelled = false
    let subscription: { cancel: () => Promise<void> } | null = null

    async function run() {
      const sub = await getMrDogeClient().matches.subscribe({ matchId })
      if (cancelled) {
        sub.cancel()
        return
      }
      subscription = sub

      setMatch(sub.snapshot)
      sub.on("snapshot", (snapshot) => setMatch(snapshot))
      sub.on("stats.upd", (stats) => setMatch((prev) => (prev ? { ...prev, stats } : prev)))
      sub.on("status.upd", ({ status }) => setMatch((prev) => (prev ? { ...prev, status } : prev)))
    }

    run().catch(() => {
      if (!cancelled) setMatch(null)
    })

    return () => {
      cancelled = true
      subscription?.cancel()
    }
  }, [matchId])

  return match
}

import { MrDoge } from "@mrdoge/client"

let client: MrDoge | null = null

/** Browser-only — the SDK authenticates via short-lived tokens minted at /api/mrdoge/token, never a raw API key. */
export function getMrDogeClient() {
  if (typeof window === "undefined") {
    throw new Error("getMrDogeClient() must be called in the browser")
  }
  if (!client) {
    client = new MrDoge({ authEndpoint: "/api/mrdoge/token" })
  }
  return client
}

import "server-only"
import { NextResponse } from "next/server"
import { MrDoge } from "@mrdoge/node"

let client: MrDoge | null = null

function getClient() {
  if (!client) {
    client = new MrDoge({ apiKey: process.env.MRDOGE_ODDS_API_KEY! })
  }
  return client
}

export async function POST() {
  const { token, expiresAt } = await getClient().tokens.create()
  return NextResponse.json({ token, expiresAt })
}
